void mainImage( out vec4 O, vec2 u )
{
    vec2 R = iResolution.xy, 
         U = ( u+u - R ) / R.y, V, A;

    for( float m,h,y ; y < .5; y += 3./R.y ) {                 // ray steps
        V = ( U - vec2(0,y-.4) ) *mat2(1, -1, 0,1.2) *1.5;     // projection on plane
        V = floor(V*32.)/32.;                                  // quantization
        A = abs( V = V*R.y/R );
        vec4 C = max(A.x,A.y) < 1. ? textureLod(iChannel0, .5+.5*V, 2.) : vec4(0); // heightfield(pos)
        h = .3*C.r + y;                                        // height
        if ( h > m ) m = h, O = C * (y-.35)*8.;                // if max, color
     // if ( h > m ) O = C * (h > m+6./R.y ? .5:1. ), m = h;   // if max, color
    }
}
